        if (frm.doc.employee) {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Salary Structure Assignment",
                    filters: { employee: frm.doc.employee },
                    fields: ["payroll_payable_account"],  // Corrected fieldname
