frappe.ui.form.on('Feedback', {
    refresh: async function (frm) {
        if (!frm.is_new() && frm.doc.status === 'Accepted') {

            // Fetch an Address record by name
            async function get_address_doc(addr_name) {
                if (addr_name) {
                    try { return await frappe.db.get_doc('Address', addr_name); }
                    catch (e) { return {}; }
                }
                return {};
            }

            // Prefer address_val, then form_val, then ultimate_default
            function field_fallback(address_val, form_val, ultimate_default = '') {
                if (address_val) return address_val;
                if (form_val)    return form_val;
                if (ultimate_default) return ultimate_default;
                return "";
            }

            // Normalize to one of the select options
            function normalize_state(state) {
                if (!state) return '';
                const opts = get_state_options().split('\n').map(s => s.trim());
                state = state.trim();
                if (opts.includes(state)) return state;
                const found = opts.find(opt => opt.toLowerCase() === state.toLowerCase());
                return found || '';
            }

            const billing_addr  = await get_address_doc(frm.doc.opportunity_billing_address);
            const shipping_addr = await get_address_doc(frm.doc.opportunity_shipping_address);

            // “Create Customer” button & dialog
            frm.add_custom_button(__('Create Customer'), function () {
                frappe.model.with_doctype('Customer', function () {
                    const customer = frappe.model.get_new_doc('Customer');

                    const dialog = new frappe.ui.Dialog({
                        title: __('Create Customer'),
                        fields: [
                            // Basic details
                            { fieldname: 'customer_name',  label: __('Customer Name'),  fieldtype: 'Data',  reqd: 1 },
                            { fieldname: 'customer_type',  label: __('Customer Type'),  fieldtype: 'Select', options: ['Company','Individual'], reqd: 1 },
                            { fieldname: 'customer_group', label: __('Customer Group'), fieldtype: 'Link', options: 'Customer Group', reqd: 1 },
                            {
                                fieldname: 'territory',
                                label: __('Territory'),
                                fieldtype: 'Link',
                                options: 'Territory',
                                reqd: 1,
                                default: frm.doc.territory || ""
                            },
                            {
                                fieldname: 'email_id',
                                label: __('Email ID'),
                                fieldtype: 'Data',
                                default: frm.doc.contact_email || ""
                            },
                            {
                                fieldname: 'phone',
                                label: __('Phone'),
                                fieldtype: 'Data',
                                default: frm.doc.contact_phone || ""
                            },

                            // Billing Address
                            { fieldname: 'section_break', fieldtype: 'Section Break', label: __('Billing Address') },
                            {
                                fieldname: 'billing_address_line1',
                                label: __('Address Line 1'),
                                fieldtype: 'Data',
                                default: field_fallback(billing_addr.address_line1, frm.doc.address_line_1)
                            },
                            {
                                fieldname: 'billing_address_line2',
                                label: __('Address Line 2'),
                                fieldtype: 'Data',
                                default: field_fallback(billing_addr.address_line2, frm.doc.address_line_2)
                            },
                            {
                                fieldname: 'billing_city',
                                label: __('City'),
                                fieldtype: 'Data',
                                default: field_fallback(billing_addr.city, frm.doc.city)
                            },
                            {
                                fieldname: 'billing_state',
                                label: __('State'),
                                fieldtype: 'Select',
                                options: get_state_options(),
                                reqd: 1,
                                default: normalize_state(
                                    field_fallback(billing_addr.state, frm.doc.state, 'West Bengal')
                                )
                            },
                            {
                                fieldname: 'billing_country',
                                label: __('Country'),
                                fieldtype: 'Link',
                                options: 'Country',
                                default: field_fallback(billing_addr.country, frm.doc.country) || 'India',
                                reqd: 1
                            },
                            {
                                fieldname: 'billing_pincode',
                                label: __('Pincode'),
                                fieldtype: 'Data',
                                default: field_fallback(billing_addr.pincode, frm.doc.pin_code)
                            },

                            // Shipping Address
                            { fieldname: 'section_break2', fieldtype: 'Section Break', label: __('Shipping Address') },
                            {
                                fieldname: 'shipping_address_line1',
                                label: __('Address Line 1'),
                                fieldtype: 'Data',
                                default: field_fallback(shipping_addr.address_line1, frm.doc.address_line_1)
                            },
                            {
                                fieldname: 'shipping_address_line2',
                                label: __('Address Line 2'),
                                fieldtype: 'Data',
                                default: field_fallback(shipping_addr.address_line2, frm.doc.address_line_2)
                            },
                            {
                                fieldname: 'shipping_city',
                                label: __('City'),
                                fieldtype: 'Data',
                                default: field_fallback(shipping_addr.city, frm.doc.city)
                            },
                            {
                                fieldname: 'shipping_state',
                                label: __('State'),
                                fieldtype: 'Select',
                                options: get_state_options(),
                                reqd: 1,
                                default: normalize_state(
                                    field_fallback(shipping_addr.state, frm.doc.state)
                                )
                            },
                            {
                                fieldname: 'shipping_country',
                                label: __('Country'),
                                fieldtype: 'Link',
                                options: 'Country',
                                default: field_fallback(shipping_addr.country, frm.doc.country) || 'India',
                                reqd: 1
                            },
                            {
                                fieldname: 'shipping_pincode',
                                label: __('Pincode'),
                                fieldtype: 'Data',
                                default: field_fallback(shipping_addr.pincode, frm.doc.pin_code)
                            }
                        ],
                        primary_action_label: __('Save'),
                        primary_action(values) {
                            // Insert Customer
                            frappe.call({
                                method: 'frappe.client.insert',
                                args: { doc: Object.assign(customer, values) },
                                callback: function (r) {
                                    if (!r.exc) {
                                        const new_customer = r.message.name;
                                        frappe.msgprint(__('Customer {0} created successfully!', [new_customer]));

                                        frm.set_value('customer', new_customer);
                                        frm.refresh_field('customer');

                                        // Create Billing Address (primary)
                                        if (values.billing_address_line1) {
                                            create_address(
                                                new_customer, values, 'Billing',
                                                values.billing_address_line1, values.billing_address_line2,
                                                values.billing_city, values.billing_state,
                                                values.billing_country, values.billing_pincode
                                            );
                                        }
                                        // Create Shipping Address
                                        if (values.shipping_address_line1) {
                                            create_address(
                                                new_customer, values, 'Shipping',
                                                values.shipping_address_line1, values.shipping_address_line2,
                                                values.shipping_city, values.shipping_state,
                                                values.shipping_country, values.shipping_pincode
                                            );
                                        }

                                        dialog.hide();
                                    }
                                }
                            });
                        }
                    });

                    dialog.show();
                });
            }, __('Actions'));

            // “Select Existing Customer” button
            frm.add_custom_button(__('Select Customer'), function () {
                frappe.prompt([
                    {
                        fieldtype: 'Link',
                        label: __('Customer'),
                        fieldname: 'customer',
                        options: 'Customer',
                        reqd: 1
                    }
                ], function (vals) {
                    frm.set_value('customer', vals.customer);
                    frm.refresh_field('customer');
                    frappe.show_alert({ message: __('Selected Customer: {0}', [vals.customer]), indicator: 'green' });
                }, __('Select Existing Customer'));
            }, __('Actions'));
        }
    }
});

/**
 * Insert Address and set primary_address on Customer if Billing
 */
function create_address(customer_name, values, address_type,
                        address_line1, address_line2,
                        city, state, country, pincode) {
    const address_doc = {
        doctype: 'Address',
        address_title: `${customer_name} ${address_type}`,
        address_line1,
        address_line2,
        city,
        state,
        country,
        pincode,
        links: [{ link_doctype: 'Customer', link_name: customer_name }],
        is_primary_address:  address_type === 'Billing'  ? 1 : 0,
        is_shipping_address: address_type === 'Shipping' ? 1 : 0,
        address_type
    };

    frappe.call({
        method: 'frappe.client.insert',
        args: { doc: address_doc },
        callback: function (res) {
            if (!res.exc && res.message) {
                const addr_name = res.message.name;
                frappe.msgprint(__(`${address_type} Address created: {0}`, [addr_name]));

                // Set Customer.primary_address field when Billing address is created
                if (address_type === 'Billing') {
                    frappe.call({
                        method: 'frappe.client.set_value',
                        args: {
                            doctype: 'Customer',
                            name: customer_name,
                            fieldname: 'customer_primary_address',
                            value: addr_name
                        },
                        callback: () => {
                            frappe.msgprint(__('Customer.primary_address set to {0}', [addr_name]));
                        }
                    });
                }
            }
        }
    });
}

